static int gx, gy;

static int hexval(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static void unhex(uint8_t *dst, const char *src, int n)
{
    for (int i = 0; i < n; i++) {
        int a = hexval(src[2*i]), b = hexval(src[2*i+1]);
        if (a < 0 || b < 0) { printf("FAIL golden hex (line %d)\n", __LINE__); ++fails; return; }
        dst[i] = (uint8_t)((a << 4) | b);
    }
}

static void pack_cache(uint8_t *out, const phx_mb_cache_t *c)
{
    int k = 0;
#define PACK(a,n) do { for (int z = 0; z < (n); z++) out[k++] = (uint8_t)(a)[z]; } while (0)
    PACK(c->intra4x4_pred_mode, 40);
    PACK(c->non_zero_count, 120);
    PACK(c->ref[0], 40);
    PACK(c->ref[1], 40);
    for (int l = 0; l < 2; l++)
        for (int i = 0; i < 40; i++)
            for (int j = 0; j < 2; j++) out[k++] = (uint8_t)c->mv[l][i][j];
    for (int l = 0; l < 2; l++)
        for (int i = 0; i < 40; i++)
            for (int j = 0; j < 2; j++) out[k++] = (uint8_t)c->mvd[l][i][j];
#undef PACK
}

static void check_bytes(const char *what, const uint8_t *got, const uint8_t *want, int n)
{
    if (memcmp(got, want, n) == 0) return;
    ++fails;
    printf("FAIL %s (mb=%d,%d):", what, gx, gy);
    int shown = 0;
    for (int i = 0; i < n; i++)
        if (got[i] != want[i]) {
            printf(" %d:%02X/%02X", i, got[i], want[i]);
            if (++shown == 8) break;
        }
    printf("\n");
}

static void set_x264_input(phx_mb_state_t *s, int forced_field)
{
    for (int xy = 0; xy < N; xy++) {
        int x = xy % W, y = xy / W;
        int b8 = 2*(y*s->b8_stride + x), b4 = 4*(y*s->b4_stride + x);
        s->type[xy] = (uint8_t)in[xy].type;
        s->slice_table[xy] = 0;
        s->field[xy] = forced_field ? 1 : (uint8_t)in[xy].field;
        s->mb_transform_size[xy] = (uint8_t)in[xy].tf;
        s->cbp[xy] = in[xy].cbp;
        memcpy(s->intra4x4_pred_mode[xy], in[xy].intra, 8);
        memcpy(s->non_zero_count[xy], in[xy].nnz, 48);
        for (int l = 0; l < 2; l++) {
            for (int j = 0; j < 4; j++)
                s->ref[l][b8 + (j>>1)*s->b8_stride + (j&1)] = in[xy].ref[l][j];
            for (int j = 0; j < 16; j++) {
                s->mv[l][b4 + (j>>2)*s->b4_stride + (j&3)][0] = in[xy].mv[l][j][0];
                s->mv[l][b4 + (j>>2)*s->b4_stride + (j&3)][1] = in[xy].mv[l][j][1];
            }
            for (int k = 0; k < 8; k++)
                for (int c = 0; c < 2; c++)
                    s->mvd[l][xy][k][c] = in[xy].mvd[l][k][c];
        }
    }
}

static void run_seq(const char *name, const phx_golden_t *g,
                    int b_mbaff, int forced_field)
{
    phx_mb_state_t *s = phx_mb_state_new(W, H);
    CHECK(s != NULL, "state allocation");
    if (!s) return;
    s->b_cabac = 1; s->slice_type = 0; /* x264 SLICE_TYPE_P */
    s->b_interlaced = forced_field;
    s->b_transform_8x8_mode = 1;
    set_x264_input(s, forced_field);

    printf("golden %s: ", name);
    int seq_fails0 = fails;
    for (int xy = 0; xy < N; xy++) {
        gx = xy % W; gy = xy / W;
        const phx_golden_t *r = &g[xy];
        phx_mb_cache_t c;
        memset(&c, 0, sizeof(c));
        phx_macroblock_cache_load(s, &c, gx, gy, b_mbaff);

        uint8_t got[560], want[560];
        pack_cache(got, &c);
        unhex(want, r->cache, sizeof(want));
        check_bytes("load cache arrays", got, want, sizeof(want));

        uint8_t tr[18], trwant[18];
        int k = 0;
        for (int l = 0; l < 2; l++) for (int j = 0; j < 3; j++)
            tr[k++] = (uint8_t)c.topright_ref[l][j];
        for (int l = 0; l < 2; l++) for (int j = 0; j < 3; j++)
            for (int comp = 0; comp < 2; comp++)
                tr[k++] = (uint8_t)c.topright_mv[l][j][comp];
        unhex(trwant, r->tr, sizeof(trwant));
        check_bytes("topright mv/ref", tr, trwant, sizeof(trwant));

        const int *f = r->flags;
        CHECK(c.i_neighbour == f[0], "i_neighbour");
        CHECK(c.i_neighbour_intra == f[1], "i_neighbour_intra");
        CHECK(c.i_neighbour_frame == f[2], "i_neighbour_frame");
        CHECK(c.i_cbp_top == f[3], "i_cbp_top");
        CHECK(c.i_cbp_left == f[4], "i_cbp_left");
        CHECK(c.i_neighbour_transform_size == f[5], "i_neighbour_transform_size");
        CHECK(c.i_neighbour_skip == f[6], "i_neighbour_skip");
        CHECK(c.b_allow_skip == f[7], "b_allow_skip");
        CHECK(c.field_decoding_flag == f[8], "field_decoding_flag");
        CHECK(c.top == f[9], "top xy");
        CHECK(c.top_y == f[10], "top y");
        CHECK(c.left[0] == f[11], "left0 xy");
        CHECK(c.left[1] == f[12], "left1 xy");
        CHECK(c.topleft == f[13], "topleft xy");
        CHECK(c.topright == f[14], "topright xy");
        CHECK(c.i_mb_topleft_y == f[15], "topleft y");
        CHECK(c.i_mb_topright_y == f[16], "topright y");
        CHECK(c.topleft_partition == f[17], "topleft_partition");
        CHECK(c.type_left[0] == f[18], "type_left");
        CHECK(c.type_top == f[19], "type_top");
        CHECK(c.type_topleft == f[20], "type_topleft");
        CHECK(c.type_topright == f[21], "type_topright");
        int lt = c.left_index == &phx_left_indices[0] ? 0
               : c.left_index == &phx_left_indices[1] ? 1
               : c.left_index == &phx_left_indices[2] ? 2
               : c.left_index == &phx_left_indices[3] ? 3 : -1;
        CHECK(lt == f[22], "left_index table");

        /* Now drive cache_save with the same explicit cache values the
         * instrumented x264 harness wrote, then compare its per-MB state. */
        for (int j = 0; j < 48; j++) {
            uint8_t v = (uint8_t)(1 + ((xy*11 + j*3) % 15));
            c.non_zero_count[phx_scan8[j]] = v;
        }
        for (int l = 0; l < 2; l++)
            for (int j = 0; j < 16; j++) {
                c.mv[l][phx_scan8[j]][0] = (int16_t)(2*(xy+1)+j);
                c.mv[l][phx_scan8[j]][1] = (int16_t)(-2*(xy+1)-j);
                c.ref[l][phx_scan8[j]] = (int8_t)((xy + j + l) & 3);
            }
        for (int l = 0; l < 2; l++)
            for (int j = 0; j < 8; j++) {
                c.mvd[l][phx_scan8[j]][0] = (int16_t)((xy + 2*j + l) & 31);
                c.mvd[l][phx_scan8[j]][1] = (int16_t)((xy + 2*j + l) & 31);
            }
        for (int j = 0; j < 8; j++)
            c.intra4x4_pred_mode[phx_scan8[j]] = (int8_t)((xy + j) % 10);
        s->type[xy] = (uint8_t)r->type;
        c.i_cbp_luma = r->cbp & 0xf;
        c.i_cbp_chroma = (r->cbp >> 4) & 3;
        c.b_transform_8x8 = r->tf;
        phx_macroblock_cache_save(s, &c, b_mbaff);

        uint8_t w[48];
        unhex(w, r->nnz, sizeof(w));
        check_bytes("saved nnz", s->non_zero_count[xy], w, sizeof(w));
        uint8_t mvw[64];
        unhex(mvw, r->mv, sizeof(mvw));
        uint8_t mvgot[64];
        for (int j = 0; j < 16; j++) {
            int hb = 4*(gy*s->b4_stride+gx) + (j>>2)*s->b4_stride + (j&3);
            mvgot[4*j+0] = (uint8_t)s->mv[0][hb][0];
            mvgot[4*j+1] = (uint8_t)(s->mv[0][hb][0] >> 8);
            mvgot[4*j+2] = (uint8_t)s->mv[0][hb][1];
            mvgot[4*j+3] = (uint8_t)(s->mv[0][hb][1] >> 8);
        }
        check_bytes("saved mv", mvgot, mvw, sizeof(mvw));
        uint8_t refw[4];
        unhex(refw, r->ref, sizeof(refw));
        uint8_t refgot[4];
        for (int j = 0; j < 4; j++)
            refgot[j] = (uint8_t)s->ref[0][2*(gy*s->b8_stride+gx)
                                          + (j>>1)*s->b8_stride + (j&1)];
        check_bytes("saved ref", refgot, refw, sizeof(refw));
        unhex(w, r->i4x4, 8);
        check_bytes("saved intra4x4_pred_mode", (uint8_t*)s->intra4x4_pred_mode[xy], w, 8);
        uint8_t mvdw[16], mvdgot[16];
        unhex(mvdw, r->mvd, sizeof(mvdw));
        for (int j = 0; j < 8; j++) {
            mvdgot[2*j]   = (uint8_t)s->mvd[0][xy][j][0];
            mvdgot[2*j+1] = (uint8_t)s->mvd[0][xy][j][1];
        }
        check_bytes("saved mvd", mvdgot, mvdw, sizeof(mvdw));
        CHECK(s->cbp[xy] == r->cbp, "saved cbp");
        CHECK(s->mb_transform_size[xy] == r->tf, "saved transform_size");
        CHECK(s->type[xy] == r->type, "saved type");
    }
    int nseq = fails - seq_fails0;
    printf("%s (%d failures)\n", nseq ? "FAILED" : "OK", nseq);
    phx_mb_state_delete(s);
}

int main(void)
{
    /* Layout and left table sanity (x264 base.h:180, macroblock.c:662/670). */
    CHECK(phx_scan8[0] == 12 && phx_scan8[1] == 13 &&
          phx_scan8[2] == 20 && phx_scan8[16] == 52, "scan8 layout");
    CHECK(phx_scan8[48] == 0 && phx_scan8[49] == 40 && phx_scan8[50] == 80,
          "scan8 chroma DC slots");
    const phx_left_table_t *lt = &phx_left_indices[3];
    CHECK(lt->intra[0] == 4 && lt->intra[3] == 3 && lt->nnz[2] == 11 &&
          lt->nnz_chroma[3] == 37, "left table progressive");

    run_seq("prog_P",       g_prog_P,       0, 0);
    run_seq("mbaff_adapt",  g_mbaff_adapt,  1, 0);
    run_seq("mbaff_forced", g_mbaff_forced, 1, 1);

    printf("%s: macroblock cache golden, %d failures\n", fails ? "FAILED" : "OK", fails);
    return fails ? 1 : 0;
}
